import { describe, test, expect } from "bun:test";
import { spawn } from "bun";

describe("validate-json", () => {
  test("validates valid JSON and exits with code 0", async () => {
    const validJson = '{"name": "test", "value": 123}';
    const proc = spawn({
      cmd: ["bun", "scripts/validate-json.ts"],
      stdin: "pipe",
      stdout: "pipe",
      stderr: "pipe",
    });

    proc.stdin.write(validJson);
    proc.stdin.end();

    const exitCode = await proc.exited;
    expect(exitCode).toBe(0);
  });

  test("rejects invalid JSON and exits with code 1", async () => {
    const invalidJson = '{"name": "test", "value": 123';
    const proc = spawn({
      cmd: ["bun", "scripts/validate-json.ts"],
      stdin: "pipe",
      stdout: "pipe",
      stderr: "pipe",
    });

    proc.stdin.write(invalidJson);
    proc.stdin.end();

    const exitCode = await proc.exited;
    expect(exitCode).toBe(1);
  });

  test("handles empty input gracefully", async () => {
    const proc = spawn({
      cmd: ["bun", "scripts/validate-json.ts"],
      stdin: "pipe",
      stdout: "pipe",
      stderr: "pipe",
    });

    proc.stdin.end();

    const exitCode = await proc.exited;
    expect(exitCode).toBe(1);
  });

  test("validates nested JSON objects", async () => {
    const nestedJson = '{"user": {"name": "test", "data": [1, 2, 3]}}';
    const proc = spawn({
      cmd: ["bun", "scripts/validate-json.ts"],
      stdin: "pipe",
      stdout: "pipe",
      stderr: "pipe",
    });

    proc.stdin.write(nestedJson);
    proc.stdin.end();

    const exitCode = await proc.exited;
    expect(exitCode).toBe(0);
  });
});

#!/usr/bin/env bun

/**
 * JSON Validator CLI
 *
 * Validates JSON input from stdin and reports success or failure.
 *
 * Usage:
 *   echo '{"valid": "json"}' | bun scripts/validate-json.ts
 *   cat file.json | bun scripts/validate-json.ts
 *   bun scripts/validate-json.ts < input.json
 *
 * Exit Codes:
 *   0 - Valid JSON
 *   1 - Invalid JSON or error
 *
 * Examples:
 *   # Valid JSON
 *   echo '{"name": "test"}' | bun scripts/validate-json.ts
 *   # Output: ✓ Valid JSON
 *   # Exit code: 0
 *
 *   # Invalid JSON
 *   echo '{"name": "test"' | bun scripts/validate-json.ts
 *   # Output: ✗ Invalid JSON: Unexpected end of JSON input
 *   # Exit code: 1
 */

async function validateJson(): Promise<void> {
  try {
    const stdin = Bun.stdin.stream();
    const reader = stdin.getReader();
    const chunks: Uint8Array[] = [];

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      chunks.push(value);
    }

    const totalLength = chunks.reduce((acc, chunk) => acc + chunk.length, 0);
    const combined = new Uint8Array(totalLength);
    let offset = 0;
    for (const chunk of chunks) {
      combined.set(chunk, offset);
      offset += chunk.length;
    }

    const input = new TextDecoder().decode(combined).trim();

    if (input.length === 0) {
      console.error("✗ Invalid JSON: Empty input");
      process.exit(1);
    }

    JSON.parse(input);
    console.log("✓ Valid JSON");
    process.exit(0);
  } catch (error) {
    const message = error instanceof Error ? error.message : "Unknown error";
    console.error(`✗ Invalid JSON: ${message}`);
    process.exit(1);
  }
}

validateJson();

