import { describe, expect, test } from "bun:test";
import { greet, add, validateJson, type Schema, type ValidationResult } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("validateJson - primitives (T1)", () => {
  test("validates string type", () => {
    const schema: Schema = { type: "string" };
    const result = validateJson("hello", schema);
    expect(result.valid).toBe(true);
    expect(result.errors).toEqual([]);
  });

  test("rejects non-string when string expected", () => {
    const schema: Schema = { type: "string" };
    const result = validateJson(42, schema);
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBeGreaterThan(0);
  });

  test("validates number type", () => {
    const schema: Schema = { type: "number" };
    const result = validateJson(42, schema);
    expect(result.valid).toBe(true);
    expect(result.errors).toEqual([]);
  });

  test("rejects non-number when number expected", () => {
    const schema: Schema = { type: "number" };
    const result = validateJson("hello", schema);
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBeGreaterThan(0);
  });

  test("validates boolean type", () => {
    const schema: Schema = { type: "boolean" };
    const result = validateJson(true, schema);
    expect(result.valid).toBe(true);
    expect(result.errors).toEqual([]);
  });

  test("rejects non-boolean when boolean expected", () => {
    const schema: Schema = { type: "boolean" };
    const result = validateJson(1, schema);
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBeGreaterThan(0);
  });
});

describe("validateJson - objects and arrays (T2)", () => {
  test("validates object with properties", () => {
    const schema: Schema = {
      type: "object",
      properties: {
        name: { type: "string" },
        age: { type: "number" }
      }
    };
    const data = { name: "Alice", age: 30 };
    const result = validateJson(data, schema);
    expect(result.valid).toBe(true);
    expect(result.errors).toEqual([]);
  });

  test("rejects object with wrong property types", () => {
    const schema: Schema = {
      type: "object",
      properties: {
        name: { type: "string" },
        age: { type: "number" }
      }
    };
    const data = { name: "Alice", age: "30" };
    const result = validateJson(data, schema);
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBeGreaterThan(0);
  });

  test("validates required fields", () => {
    const schema: Schema = {
      type: "object",
      properties: {
        name: { type: "string" },
        age: { type: "number" }
      },
      required: ["name"]
    };
    const data = { name: "Alice" };
    const result = validateJson(data, schema);
    expect(result.valid).toBe(true);
  });

  test("rejects missing required fields", () => {
    const schema: Schema = {
      type: "object",
      properties: {
        name: { type: "string" },
        age: { type: "number" }
      },
      required: ["name"]
    };
    const data = { age: 30 };
    const result = validateJson(data, schema);
    expect(result.valid).toBe(false);
    expect(result.errors.some(e => e.includes("required"))).toBe(true);
  });

  test("validates arrays", () => {
    const schema: Schema = {
      type: "array",
      items: { type: "number" }
    };
    const result = validateJson([1, 2, 3], schema);
    expect(result.valid).toBe(true);
    expect(result.errors).toEqual([]);
  });

  test("rejects arrays with wrong item types", () => {
    const schema: Schema = {
      type: "array",
      items: { type: "number" }
    };
    const result = validateJson([1, "two", 3], schema);
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBeGreaterThan(0);
  });

  test("validates nested objects", () => {
    const schema: Schema = {
      type: "object",
      properties: {
        user: {
          type: "object",
          properties: {
            name: { type: "string" },
            active: { type: "boolean" }
          }
        }
      }
    };
    const data = { user: { name: "Bob", active: true } };
    const result = validateJson(data, schema);
    expect(result.valid).toBe(true);
  });

  test("handles null values", () => {
    const schema: Schema = { type: "string" };
    const result = validateJson(null, schema);
    expect(result.valid).toBe(false);
  });

  test("handles undefined values", () => {
    const schema: Schema = { type: "string" };
    const result = validateJson(undefined, schema);
    expect(result.valid).toBe(false);
  });

  test("handles empty objects", () => {
    const schema: Schema = { type: "object", properties: {} };
    const result = validateJson({}, schema);
    expect(result.valid).toBe(true);
  });

  test("handles empty arrays", () => {
    const schema: Schema = { type: "array", items: { type: "number" } };
    const result = validateJson([], schema);
    expect(result.valid).toBe(true);
  });
});

describe("validateJson - error reporting (T3)", () => {
  test("provides detailed error messages for type mismatches", () => {
    const schema: Schema = { type: "string" };
    const result = validateJson(42, schema);
    expect(result.valid).toBe(false);
    expect(result.errors[0]).toContain("string");
    expect(result.errors[0]).toContain("number");
  });

  test("provides path information for nested errors", () => {
    const schema: Schema = {
      type: "object",
      properties: {
        user: {
          type: "object",
          properties: {
            age: { type: "number" }
          }
        }
      }
    };
    const data = { user: { age: "invalid" } };
    const result = validateJson(data, schema);
    expect(result.valid).toBe(false);
    expect(result.errors[0]).toContain("user.age");
  });

  test("provides index information for array errors", () => {
    const schema: Schema = {
      type: "array",
      items: { type: "number" }
    };
    const result = validateJson([1, "invalid", 3], schema);
    expect(result.valid).toBe(false);
    expect(result.errors[0]).toContain("[1]");
  });

  test("reports all errors, not just first", () => {
    const schema: Schema = {
      type: "object",
      properties: {
        name: { type: "string" },
        age: { type: "number" },
        active: { type: "boolean" }
      }
    };
    const data = { name: 123, age: "invalid", active: "yes" };
    const result = validateJson(data, schema);
    expect(result.valid).toBe(false);
    expect(result.errors.length).toBe(3);
  });
});

describe("validateJson - performance (T4)", () => {
  test("handles large objects efficiently", () => {
    const schema: Schema = {
      type: "object",
      properties: {
        items: {
          type: "array",
          items: {
            type: "object",
            properties: {
              id: { type: "number" },
              name: { type: "string" }
            }
          }
        }
      }
    };

    const data = {
      items: Array.from({ length: 1000 }, (_, i) => ({
        id: i,
        name: `Item ${i}`
      }))
    };

    const start = performance.now();
    const result = validateJson(data, schema);
    const duration = performance.now() - start;

    expect(result.valid).toBe(true);
    expect(duration).toBeLessThan(50);
  });

  test("short-circuits on first error when validation fails early", () => {
    const schema: Schema = {
      type: "array",
      items: { type: "number" }
    };

    const data = Array.from({ length: 10000 }, (_, i) => i < 5 ? i : "invalid");

    const result = validateJson(data, schema);
    expect(result.valid).toBe(false);
  });
});

