/**
 * Utility functions for the eval test project.
 */

/**
 * Greet someone by name.
 */
export function greet(name: string): string {
  return `Hello, ${name}!`;
}

/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

/**
 * JSON Schema type definition for validation.
 * Supports primitive types, objects, and arrays with nested validation.
 */
export type Schema = {
  type: "string" | "number" | "boolean" | "object" | "array";
  properties?: Record<string, Schema>;
  required?: string[];
  items?: Schema;
};

/**
 * Result of JSON validation operation.
 */
export type ValidationResult = {
  valid: boolean;
  errors: string[];
};

/**
 * Validates JSON data against a schema.
 *
 * High-performance validator using native type guards and minimal allocations.
 * Reports all validation errors with detailed path information.
 *
 * @param data - The data to validate
 * @param schema - The schema to validate against
 * @param path - Internal: current path for error reporting
 * @returns ValidationResult with valid flag and error messages
 *
 * @example
 * ```typescript
 * const schema = {
 *   type: "object",
 *   properties: {
 *     name: { type: "string" },
 *     age: { type: "number" }
 *   },
 *   required: ["name"]
 * };
 *
 * const result = validateJson({ name: "Alice", age: 30 }, schema);
 * if (!result.valid) {
 *   console.error("Validation errors:", result.errors);
 * }
 * ```
 */
export function validateJson(
  data: unknown,
  schema: Schema,
  path: string = ""
): ValidationResult {
  const errors: string[] = [];

  const currentPath = path || "root";

  switch (schema.type) {
    case "string":
      if (typeof data !== "string") {
        errors.push(
          `${currentPath}: Expected string, got ${typeof data}`
        );
      }
      break;

    case "number":
      if (typeof data !== "number") {
        errors.push(
          `${currentPath}: Expected number, got ${typeof data}`
        );
      }
      break;

    case "boolean":
      if (typeof data !== "boolean") {
        errors.push(
          `${currentPath}: Expected boolean, got ${typeof data}`
        );
      }
      break;

    case "array":
      if (!Array.isArray(data)) {
        errors.push(
          `${currentPath}: Expected array, got ${typeof data}`
        );
      } else if (schema.items) {
        for (let i = 0; i < data.length; i++) {
          const itemResult = validateJson(
            data[i],
            schema.items,
            `${currentPath}[${i}]`
          );
          errors.push(...itemResult.errors);
        }
      }
      break;

    case "object":
      if (typeof data !== "object" || data === null || Array.isArray(data)) {
        errors.push(
          `${currentPath}: Expected object, got ${data === null ? "null" : Array.isArray(data) ? "array" : typeof data}`
        );
      } else {
        if (schema.required) {
          for (const requiredField of schema.required) {
            if (!(requiredField in data)) {
              errors.push(
                `${currentPath}: Missing required field '${requiredField}'`
              );
            }
          }
        }

        if (schema.properties) {
          for (const [key, propSchema] of Object.entries(schema.properties)) {
            if (key in data) {
              const propPath = path ? `${path}.${key}` : key;
              const propResult = validateJson(
                (data as Record<string, unknown>)[key],
                propSchema,
                propPath
              );
              errors.push(...propResult.errors);
            }
          }
        }
      }
      break;
  }

  return {
    valid: errors.length === 0,
    errors
  };
}

